DO $body$ DECLARE source text; BEGIN SELECT pg_get_functiondef('trip_private.night_flow_action(uuid,integer,text)'::regprocedure) INTO source; source:=replace(source, 'SELECT category INTO v_category FROM unnest(ARRAY[''travel'',''food'',''childhood'',''deep'']::text[]) category ORDER BY random() LIMIT 1;', 'v_category := (ARRAY[''travel'',''food'',''childhood'',''deep'']::text[])[(p_week-1) % 4+1];'); IF source NOT LIKE '%(p_week-1) % 4+1%' THEN RAISE EXCEPTION 'Warm-up rotation patch did not apply'; END IF; EXECUTE source; END $body$;